const fs = require('fs');
const vm = require('vm');
const source = fs.readFileSync('app.js', 'utf8');
const wordBlock = source.match(/const WORDS = \{[\s\S]*?\n\};/)[0];
const helpers = source.slice(source.indexOf('function wordsFor('), source.indexOf('const HINT_RULES'));
const context = { Math };
vm.createContext(context);
vm.runInContext(`${wordBlock}\n${helpers}\nglobalThis.api={WORDS,wordsFor,chooseWord};`, context);
const { WORDS, chooseWord } = context.api;
const categories = Object.keys(WORDS);
const used = [];
const counts = Object.fromEntries(categories.map(category => [category, 0]));
for (let i = 0; i < Object.values(WORDS).reduce((sum, list) => sum + list.split(',').length, 0); i++) {
  const selection = chooseWord(categories, used);
  if (!selection || !categories.includes(selection.category)) throw new Error('Missing or unselected category');
  if (used.includes(selection.word)) throw new Error(`Repeat before exhaustion: ${selection.word}`);
  counts[selection.category]++;
  used.push(selection.word);
}
const uniquePool = new Set(categories.flatMap(category => WORDS[category].split(',').map(word => word.trim())));
if (used.length !== uniquePool.size) throw new Error(`Expected ${uniquePool.size} unique pool words, got ${used.length}`);
const exhausted = chooseWord(categories, used);
if (!exhausted || !used.includes(exhausted.word) || used.length !== 1) throw new Error('Pool exhaustion did not reset the no-repeat cycle');
const selected = ['Food', 'Animals'];
const selectedUsed = [];
for (let i = 0; i < 10; i++) {
 const selection = chooseWord(selected, selectedUsed);
 if (!selected.includes(selection.category)) throw new Error(`Selected unrequested category ${selection.category}`);
 selectedUsed.push(selection.word);
}
console.log(`Selection tests passed: ${used.length} distinct pool words, reset after exhaustion; selected-category restriction passed.`);
console.log('Category picks across a full cycle:', counts);
