const fs = require('fs');
const vm = require('vm');
const source = fs.readFileSync('app.js', 'utf8');
const data = source.match(/const WORDS = \{[\s\S]*?\n\};/)[0];
const hints = source.slice(source.indexOf('const HINT_RULES'), source.indexOf('\nfunction render()'));
const context = { Math };
vm.createContext(context);
vm.runInContext(`${data}\n${hints}\nglobalThis.api={WORDS,generateHint};`, context);
const { WORDS, generateHint } = context.api;
let checked = 0;
for (const [category, list] of Object.entries(WORDS)) {
 for (const raw of list.split(',')) {
  const word = raw.trim();
  const hint = generateHint(word, category);
  if (!hint) throw new Error(`Missing hint for ${category}: ${word}`);
  const words = hint.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const secret = word.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  for (let i = 0; i <= words.length - secret.length; i++) {
   if (secret.every((part, j) => words[i + j] === part)) throw new Error(`Hint reveals ${word}: ${hint}`);
  }
  checked++;
 }
}
console.log(`Hint compatibility passed for ${checked} words (non-empty, no exact secret phrase).`);
